using helengine.editor.assimp;
using helengine.editor.tests.testing;
using Xunit;

namespace helengine.editor.tests {
    /// <summary>
    /// Verifies scenes that instantiate a blueprint generated by scene-mode model import package for webgpu.
    /// </summary>
    public class GeneratedBlueprintPackagingTests : IDisposable {
        /// <summary>
        /// Temporary project root used for each test.
        /// </summary>
        readonly string ProjectRootPath;

        /// <summary>
        /// Temporary assets root holding the copied fixture.
        /// </summary>
        readonly string AssetsRootPath;

        /// <summary>
        /// Temporary build output root.
        /// </summary>
        readonly string BuildRootPath;

        /// <summary>
        /// Initializes isolated project directories for each test case.
        /// </summary>
        public GeneratedBlueprintPackagingTests() {
            ProjectRootPath = Path.Combine(Path.GetTempPath(), "helengine-generated-blueprint-packaging-tests", Guid.NewGuid().ToString("N"));
            AssetsRootPath = Path.Combine(ProjectRootPath, "assets");
            BuildRootPath = Path.Combine(ProjectRootPath, "Build");
            Directory.CreateDirectory(AssetsRootPath);
            Directory.CreateDirectory(BuildRootPath);
        }

        /// <summary>
        /// Deletes the temporary project after each test.
        /// </summary>
        public void Dispose() {
            if (Directory.Exists(ProjectRootPath)) {
                Directory.Delete(ProjectRootPath, true);
            }
        }

        /// <summary>
        /// Ensures the hinged box blueprint packages its entity tree and every mesh resolves to a packaged model file.
        /// </summary>
        [Fact]
        public void SceneWithGeneratedBlueprintInstance_packagesHierarchyAndModels() {
            SceneAsset packagedScene = ImportAndPackage("hinged_box.gltf");

            SceneEntityAsset instanceRoot = Assert.Single(packagedScene.RootEntities);
            Assert.Equal(new float3(7f, 8f, 9f), instanceRoot.LocalPosition);
            SceneEntityAsset blueprintRoot = Assert.Single(instanceRoot.Children);
            Assert.Equal(2, blueprintRoot.Children.Length);
            SceneEntityAsset baseEntity = blueprintRoot.Children[0];
            Assert.Equal("Base", baseEntity.Name);
            Assert.Equal(1f, baseEntity.LocalPosition.X, 4);
            Assert.Equal(2f, baseEntity.LocalPosition.Y, 4);
            Assert.Equal(3f, baseEntity.LocalPosition.Z, 4);
            SceneEntityAsset lid = baseEntity.Children[0];
            Assert.Equal("Lid", lid.Name);
            Assert.Equal(2f, lid.LocalScale.X, 4);
            Assert.Equal(0.3826834f, lid.LocalOrientation.Y, 4);
            Assert.Equal(0.9238795f, lid.LocalOrientation.W, 4);
            Assert.Equal(5f, lid.Children[0].LocalPosition.Z, 4);

            Assert.True(CountComponents(instanceRoot, "helengine.MeshComponent") >= 1);
            AssertModelReferencesArePackaged(packagedScene, 1);
        }

        /// <summary>
        /// Ensures a node with two mesh components packages both of them.
        /// </summary>
        [Fact]
        public void SceneWithGeneratedBlueprintInstance_packagesNodeWithTwoMeshes() {
            SceneAsset packagedScene = ImportAndPackage("two_primitives.gltf");

            SceneEntityAsset instanceRoot = Assert.Single(packagedScene.RootEntities);
            int meshComponents = CountComponents(instanceRoot, "helengine.MeshComponent");
            Assert.True(meshComponents >= 2, "Expected at least two mesh components, found " + meshComponents);
            AssertModelReferencesArePackaged(packagedScene, 2);
        }

        /// <summary>
        /// Imports a fixture in scene mode, instantiates its blueprint in a scene and packages it for webgpu.
        /// </summary>
        /// <param name="fixtureName">Fixture file name.</param>
        /// <returns>Packaged scene.</returns>
        SceneAsset ImportAndPackage(string fixtureName) {
            string sourcePath = Path.Combine(AssetsRootPath, fixtureName);
            File.Copy(Path.Combine(AppContext.BaseDirectory, "fixtures", "scene", fixtureName), sourcePath);
            ContentManager contentManager = new ContentManager(new HostFileSystemContentStreamSource(AssetsRootPath));
            AssetImportManager manager = new AssetImportManager(ProjectRootPath, contentManager);
            manager.RegisterModelImporter(new ModelImporterRegistration("assimp", new HelengineAssimpImporter(), new[] { ".gltf" }));
            ModelAssetImportSettings settings = manager.LoadOrCreateModelImportSettings(sourcePath);
            settings.Mode = ModelImportMode.Scene;
            manager.SaveModelImportSettings(sourcePath, settings);
            manager.ImportModel(sourcePath);

            string blueprintRelativePath = fixtureName + ".generated/" + Path.GetFileNameWithoutExtension(fixtureName) + ".hblueprint";
            string sceneId = "Scenes/Main.helen";
            string sceneFullPath = Path.Combine(AssetsRootPath, "Scenes", "Main.helen");
            Directory.CreateDirectory(Path.GetDirectoryName(sceneFullPath));
            SceneAsset scene = new SceneAsset {
                Id = sceneId,
                AuthoringAssetId = Guid.NewGuid().ToString("N"),
                RootEntities = [
                    new SceneEntityAsset {
                        Id = 100u,
                        Name = "Instance Root",
                        LocalPosition = new float3(7f, 8f, 9f),
                        LocalScale = float3.One,
                        LocalOrientation = float4.Identity,
                        LayerMask = EditorLayerMasks.SceneObjects,
                        Components = [
                            SerializeComponent(new BlueprintInstanceComponent {
                                BlueprintAssetReference = SceneAssetReferenceTestFactory.CreateCurrentFileSystem(blueprintRelativePath)
                            })
                        ],
                        Children = Array.Empty<SceneEntityAsset>()
                    }
                ],
                AssetReferences = Array.Empty<SceneAssetReference>()
            };
            using (FileStream stream = File.Create(sceneFullPath)) {
                AssetSerializer.Serialize(stream, scene);
            }

            EditorPlatformBuildScenePackager packager = new EditorPlatformBuildScenePackager(
                ProjectRootPath,
                Array.Empty<IAssetImporterRegistration>(),
                "webgpu",
                TestGeneratedAssetGraph.CreateShaderLibrary());
            packager.Package([sceneId], BuildRootPath);

            string packagedPath = Path.Combine(BuildRootPath, PackagedScenePathResolver.BuildRelativePath(sceneId, 0).Replace('/', Path.DirectorySeparatorChar));
            using FileStream packagedStream = File.OpenRead(packagedPath);
            return global::helengine.PackagedAssetBinarySerializer.DeserializeSceneAsset(packagedStream);
        }

        /// <summary>
        /// Asserts every file-system reference of the packaged scene exists in the build root and that enough of them are packaged models.
        /// </summary>
        /// <param name="scene">Packaged scene.</param>
        /// <param name="minimumModels">Minimum number of packaged model references.</param>
        void AssertModelReferencesArePackaged(SceneAsset scene, int minimumModels) {
            int models = 0;
            List<string> paths = new List<string>();
            for (int index = 0; index < scene.AssetReferences.Length; index++) {
                SceneAssetReference reference = scene.AssetReferences[index];
                if (reference.SourceKind != SceneAssetReferenceSourceKind.FileSystem) {
                    continue;
                }
                paths.Add(reference.RelativePath);
                string fullPath = Path.Combine(BuildRootPath, reference.RelativePath.Replace('/', Path.DirectorySeparatorChar));
                Assert.True(File.Exists(fullPath), "Missing packaged file for " + reference.RelativePath);
                using FileStream stream = File.OpenRead(fullPath);
                Asset asset;
                try {
                    asset = global::helengine.PackagedAssetBinarySerializer.Deserialize(stream);
                } catch (Exception) {
                    continue;
                }
                if (asset is ModelAsset) {
                    models++;
                }
            }
            Assert.True(models >= minimumModels, "Expected packaged models, found " + models + ". References: " + string.Join(", ", paths));
            Assert.Equal(minimumModels, models);
        }

        /// <summary>
        /// Counts components of one type in an entity subtree.
        /// </summary>
        /// <param name="entity">Subtree root.</param>
        /// <param name="componentTypeId">Component type id.</param>
        /// <returns>Number of matching components.</returns>
        static int CountComponents(SceneEntityAsset entity, string componentTypeId) {
            int count = 0;
            for (int index = 0; index < entity.Components.Length; index++) {
                if (entity.Components[index].ComponentTypeId == componentTypeId) {
                    count++;
                }
            }
            for (int index = 0; index < entity.Children.Length; index++) {
                count += CountComponents(entity.Children[index], componentTypeId);
            }
            return count;
        }

        /// <summary>
        /// Serializes one component into its scene record.
        /// </summary>
        /// <param name="component">Component to serialize.</param>
        /// <returns>Serialized record.</returns>
        static SceneComponentAssetRecord SerializeComponent(Component component) {
            ComponentPersistenceRegistry registry = new ComponentPersistenceRegistry();
            return registry.GetDescriptor(component).SerializeComponent(component, 0, new EntityComponentSaveState());
        }
    }
}
